import Header from '../../components/Header'
import QuickActions from '../../components/QuickActions'
import BookingsList from '../../components/BookingsList'
import LiveQueue from '../../components/LiveQueue'
import Notifications from '../../components/Notifications'

async function getMockBookings(){
  try{
    const res = await fetch('http://localhost:3000/api/bookings')
    if(!res.ok) throw new Error('No')
    return res.json()
  }catch(e){
    return [
      {id:'BK-2024-00123',service:'Passport Renewal',date:'20 May 2024, 10:30 AM',status:'Confirmed'},
      {id:'BK-2024-00124',service:'Driving License',date:'22 May 2024, 02:00 PM',status:'Scheduled'},
      {id:'BK-2024-00125',service:'Trade License',date:'25 May 2024, 11:00 AM',status:'Pending'},
    ]
  }
}

export default async function Page(){
  const bookings = await getMockBookings()
  const notifications = [
    {id:'n1',title:'Payment successful',body:'Your payment of ₹2,500 was successful.',time:'5m ago'},
    {id:'n2',title:'Appointment reminder',body:'Your appointment is tomorrow at 10:30 AM.',time:'1h ago'},
  ]

  return (
    <div>
      <Header />
      <main style={{padding:24,maxWidth:1100,margin:'0 auto'}}>
        <h1 style={{marginTop:12}}>Welcome back</h1>
        <QuickActions />
        <div style={{display:'grid',gridTemplateColumns:'1fr 320px',gap:12,alignItems:'start'}}>
          <div style={{display:'grid',gap:12}}>
            <BookingsList items={bookings} />
            <div style={{display:'flex',gap:12}}>
              <LiveQueue />
              <div style={{flex:1}}>
                <div style={{background:'#fff',padding:16,borderRadius:10}}>
                  <h4 style={{margin:0}}>Recent Payments</h4>
                  <ul style={{marginTop:8}}>
                    <li>INV-2024-0098 — ₹2,500 — 20 May 2024</li>
                    <li>INV-2024-0097 — ₹1,200 — 15 May 2024</li>
                  </ul>
                </div>
              </div>
            </div>
          </div>
          <Notifications items={notifications} />
        </div>
      </main>
    </div>
  )
}
"use client"
import React from 'react'
import { getBookings } from '../../lib/api'
import { useBookings } from '../../lib/hooks/useBookings'

export default function DashboardPage() {
  const { data, loading } = useBookings()

  return (
    <div>
      <h1 className="text-2xl font-semibold mb-4">My Appointments</h1>
      {loading ? (
        <div className="space-y-2">
          <div className="h-12 skeleton rounded" />
          <div className="h-12 skeleton rounded" />
        </div>
      ) : (
        <ul className="space-y-3">
          {data?.map(b=> (
            <li key={b.id} className="p-3 border rounded flex justify-between">
              <div>
                <div className="font-medium">Dr. {b.doctorName}</div>
                <div className="text-sm text-gray-600">{b.date} • {b.slot}</div>
              </div>
              <div className="text-sm font-semibold">{b.status}</div>
            </li>
          ))}
        </ul>
      )}
    </div>
  )
}
